Import("env")

from pathlib import Path

project = Path(env.subst("$PROJECT_DIR"))
web_dir = project / "web"
out_file = project / "src" / "web_assets.h"

files = {
    "WEB_INDEX_HTML": "index.html",
    "WEB_STYLE_CSS": "style.css",
    "WEB_APP_JS": "app.js",
}

parts = [
    "// Auto-generated by scripts/embed_web.py — do not edit.\n",
    "#pragma once\n\n",
]

for name, filename in files.items():
    text = (web_dir / filename).read_text(encoding="utf-8")
    if ")BILLIARD\"" in text:
        raise RuntimeError(f"{filename} contains the raw-string delimiter")
    parts.append(f'static const char {name}[] PROGMEM = R"BILLIARD({text})BILLIARD";\n\n')

out_file.write_text("".join(parts), encoding="utf-8")
print(f"embed_web: wrote {out_file}")
